          style: { padding: "8px 12px", borderRadius: "8px", fontSize: "12px", background: status.ok ? "rgba(16,185,129,0.1)" : "rgba(239,68,68,0.1)", color: status.ok ? "#059669" : "#dc2626", marginTop: "8px" },
